package com.movieworth.api.boxoffice;
import com.movieworth.api.movie.Movie;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="box_office_collections",uniqueConstraints=@UniqueConstraint(columnNames={"movie_id","collection_date","source"})) public class CollectionSnapshot{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="movie_id",nullable=false)Movie movie;@Column(name="collection_date",nullable=false)LocalDate collectionDate;@Column(name="india_net_cr")BigDecimal indiaNetCr;@Column(name="india_gross_cr")BigDecimal indiaGrossCr;@Column(name="overseas_gross_cr")BigDecimal overseasGrossCr;@Column(name="worldwide_gross_cr")BigDecimal worldwideGrossCr;@Column(nullable=false)String source;@Column(name="source_url")String sourceUrl;@Column(name="created_at")OffsetDateTime createdAt;
@PrePersist void created(){createdAt=OffsetDateTime.now();}public Long getId(){return id;}public Movie getMovie(){return movie;}public void setMovie(Movie m){movie=m;}public LocalDate getCollectionDate(){return collectionDate;}public void setCollectionDate(LocalDate d){collectionDate=d;}public BigDecimal getIndiaNetCr(){return indiaNetCr;}public void setIndiaNetCr(BigDecimal v){indiaNetCr=v;}public BigDecimal getIndiaGrossCr(){return indiaGrossCr;}public void setIndiaGrossCr(BigDecimal v){indiaGrossCr=v;}public BigDecimal getOverseasGrossCr(){return overseasGrossCr;}public void setOverseasGrossCr(BigDecimal v){overseasGrossCr=v;}public BigDecimal getWorldwideGrossCr(){return worldwideGrossCr;}public void setWorldwideGrossCr(BigDecimal v){worldwideGrossCr=v;}public String getSource(){return source;}public void setSource(String v){source=v;}public String getSourceUrl(){return sourceUrl;}public void setSourceUrl(String v){sourceUrl=v;}}
